// ADR-013/013b: verify the IAM-Signature, idempotently create the non-payroll ERPNext HR worker, and bind
// the HR-EMP id back to the EMITTING IAM (ev.iamCallbackBaseUrl). n8n is the only ERPNext writer (ADR-009).
const crypto = require('crypto');
const whk = $('Webhook (onboarded)').first().json;
const ev = whk.body;
const hdr = whk.headers || {};
const sig = hdr['iam-signature'] || hdr['IAM-Signature'] || '';
const key = $env.HR_LIFECYCLE_SIGNING_KEY || '';
if (key) {
  const want = crypto.createHmac('sha256', key).update(JSON.stringify(ev), 'utf8').digest('hex');
  if (want !== sig) throw new Error('bad IAM-Signature');
}
const iamBase = ev.iamCallbackBaseUrl || 'https://iam-dev.10.0.0.200.nip.io';
const auth = 'token ' + $env.ERPNEXT_API_KEY + ':' + $env.ERPNEXT_API_SECRET;
const H = { Authorization: auth, 'content-type': 'application/json' };
const filt = encodeURIComponent(JSON.stringify([['custom_iam_collaborator_id', '=', ev.idempotencyKey]]));
const found = await this.helpers.httpRequest({ method:'GET', url:'https://erp.devandre.sbs/api/resource/Employee?filters=' + filt, headers:H, json:true, skipSslCertificateValidation:true });
let hrName;
if (found.data && found.data.length) { hrName = found.data[0].name; }
else {
  const emp = await this.helpers.httpRequest({ method:'POST', url:'https://erp.devandre.sbs/api/resource/Employee', headers:H, body:{ first_name: ev.displayName, employment_type: ev.engagementType, company:'Ktayl Solutions', status:'Active', date_of_joining: new Date().toISOString().slice(0,10), custom_agency_or_firm: ev.firm||'', custom_iam_collaborator_id: ev.idempotencyKey }, json:true, skipSslCertificateValidation:true });
  hrName = emp.data.name;
}
await this.helpers.httpRequest({ method:'POST', url: iamBase + '/api/collaborators/' + ev.collaboratorId + '/hr-worker-ref', headers:{ 'X-IAM-Service-Key': $env.IAM_SERVICE_KEY, 'content-type':'application/json' }, body:{ hrWorkerRef: hrName }, json:true, skipSslCertificateValidation:true });
return [{ json: { ok:true, hrWorkerRef: hrName, boundTo: iamBase } }];
